function validate([sx, sy, fx, fy, t]) {
  if (![sx, sy, fx, fy, t].every(Number.isInteger)) return 'All inputs are whole numbers.';
  if ([sx, sy, fx, fy].some(v => v < 1 || v > 1000000000)) return 'Coordinates are between 1 and 10^9.';
  if (t < 0 || t > 1000000000) return 't is between 0 and 10^9.';
  return null;
}

