function isReachableAtTime(sx, sy, fx, fy, t) {
  const dx = fx - sx, dy = fy - sy;
  // Each second changes each coordinate by at most 1.
  if (Math.abs(dx) > t || Math.abs(dy) > t) return false;
  if (t <= 12) {
    // Short walks: simulate the set of offsets reachable after each second.
    let cells = new Set(['0,0']);
    for (let s = 0; s < t; s++) {
      const next = new Set();
      for (const key of cells) {
        const [x, y] = key.split(',').map(Number);
        for (let a = -1; a <= 1; a++)
          for (let b = -1; b <= 1; b++)
            if (a !== 0 || b !== 0) next.add(`${x + a},${y + b}`);
      }
      cells = next;
    }
    return cells.has(`${dx},${dy}`);
  }
  // Long walks: x makes t - zx moves of +-1 and stays still zx times (same for y), and the
  // still seconds of x and y must differ, so zx + zy <= t. Small zx, zy are always best.
  for (const zx of [0, 1, 2, 3])
    for (const zy of [0, 1, 2, 3]) {
      const okX = t - zx >= Math.abs(dx) && (t - zx - Math.abs(dx)) % 2 === 0;
      const okY = t - zy >= Math.abs(dy) && (t - zy - Math.abs(dy)) % 2 === 0;
      if (okX && okY && zx + zy <= t) return true;
    }
  return false;
}

