function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const LIMIT = 1000000000;
  if (size === 'large') {
    const sx = int(1, LIMIT), sy = int(1, LIMIT), fx = int(1, LIMIT), fy = int(1, LIMIT);
    const fewest = Math.max(Math.abs(fx - sx), Math.abs(fy - sy));
    const t = rand() < 0.5 ? int(0, LIMIT) : Math.min(LIMIT, Math.max(0, fewest + int(-2, 2)));
    return [sx, sy, fx, fy, t];
  }
  const base = rand() < 0.2 ? LIMIT - 6 : 0;
  const sx = base + int(1, 6), sy = base + int(1, 6);
  const same = rand() < 0.25;
  const fx = same ? sx : base + int(1, 6), fy = same ? sy : base + int(1, 6);
  const t = rand() < 0.3 ? int(0, 2) : int(0, 10);
  return [sx, sy, fx, fy, t];
}
